		if (GlobalScript.inst.gameState.resultOfEvents[488] != 3 && GlobalScript.inst.gameState.allcountries[17].Gosstroy == 1 && GlobalScript.inst.gameState.allcountries[17].dev <= 0 && GlobalScript.inst.gameState.allcountries[16].proprc && GlobalScript.inst.gameState.allcountries[16].Gosstroy == 1)
